<div class="card p-4 p-md-5"><div class="admin-head"><div><span class="eyebrow">PRODUCTOS</span><h2 class="section"><?=$p?'Editar producto':'Nuevo producto'?></h2><p>Información comercial, precios, existencias y publicación.</p></div><a href="/?r=adminProducts" class="btn soft">Volver</a></div><form method="post" action="/?r=productSave" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e($p['id']??'')?>"><input type="hidden" name="existing_image" value="<?=e($p['image']??'uploads/images.jpg')?>"><div class="row g-3"><div class="col-md-3"><label>SKU</label><input class="form-control" name="sku" maxlength="30" required value="<?=e($p['sku']??'')?>" placeholder="MM-001"></div><div class="col-md-5"><label>Nombre</label><input class="form-control" name="name" maxlength="120" required value="<?=e($p['name']??'')?>"></div><div class="col-md-4"><label>Marca</label><input class="form-control" name="brand" maxlength="80" value="<?=e($p['brand']??'')?>"></div><div class="col-12"><label>Descripción</label><textarea class="form-control" name="description" maxlength="1000" rows="4"><?=e($p['description']??'')?></textarea></div><div class="col-md-3"><label>Precio normal</label><input class="form-control" type="number" min="0" step=".01" name="price" required value="<?=e($p['price']??'')?>"></div><div class="col-md-3"><label>Precio oferta</label><input class="form-control" type="number" min="0" step=".01" name="sale_price" value="<?=e($p['sale_price']??0)?>"></div><div class="col-md-3"><label>Unidad de venta</label><select class="form-select searchable-select" name="unit_type" required><?php foreach(['unidad'=>'Unidades','lb'=>'Libras (lb)','kg'=>'Kilogramos (kg)','paquete'=>'Paquetes','caja'=>'Cajas','litro'=>'Litros','metro'=>'Metros'] as $uv=>$ul):?><option value="<?=$uv?>" <?=($p['unit_type']??'unidad')===$uv?'selected':''?>><?=$ul?></option><?php endforeach;?></select><small class="text-muted">El precio se interpreta por esta unidad.</small></div><div class="col-md-2"><label>Stock</label><input class="form-control" type="number" min="0" name="stock" required value="<?=e($p['stock']??0)?>"></div><div class="col-md-2"><label>Stock mínimo</label><input class="form-control" type="number" min="0" name="min_stock" required value="<?=e($p['min_stock']??3)?>"></div><div class="col-md-2"><label>Estado</label><select class="form-select searchable-select" name="status"><option value="activo" <?=($p['status']??'activo')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($p['status']??'')==='inactivo'?'selected':''?>>Inactivo</option></select></div><div class="col-md-4"><label>Categoría</label><select class="form-select searchable-select" name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($p['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-8"><label>Imagen del producto</label><input class="form-control" type="file" name="image_file" accept="image/jpeg,image/png,image/webp"><small class="text-muted">JPG, PNG o WEBP · máximo 5 MB. Si no seleccionas una nueva imagen, se conserva la actual.</small></div><?php if($p):?><div class="col-12"><img src="/<?=e($p['image'])?>" class="product-preview" alt=""></div><?php endif;?></div><button class="btn grad mt-4 px-5">Guardar producto</button></form></div>
